class App:
    def __init__(self):
        self.befehle = {}

    def befehl(self, name):
        def deko(func):
            self.befehle[name] = func
            return func
        return deko

    def run(self, eingaben):
        for zeile in eingaben:
            name, *args = zeile.split()
            func = self.befehle.get(name)
            if func is None:
                print("Unbekannt:", name)
            else:
                print(func(*args))

app = App()

@app.befehl("hallo")
def hallo(name):
    return f"Servus, {name}!"

@app.befehl("add")
def add(a, b):
    return int(a) + int(b)

app.run(["hallo Lena", "add 2 3", "xyz"])
# Servus, Lena!
# 5
# Unbekannt: xyz

from abc import ABC, abstractmethod

class Importer(ABC):
    def run(self, text):        # fixer Ablauf
        zeilen = self.lesen(text)
        ok = [z for z in zeilen
              if self.pruefen(z)]
        print(f"{len(ok)} von {len(zeilen)}")

    @abstractmethod
    def lesen(self, text): ...

    def pruefen(self, zeile):   # Hook
        return True             # Standard

class CsvImporter(Importer):
    def lesen(self, text):
        return text.strip().split("\n")

    def pruefen(self, zeile):
        return ";" in zeile

CsvImporter().run("a;1\nb;2\nkaputt")
# 2 von 3

